.chapter-container {
  --ink: #2d3748;
  --muted: #718096;
  --accent: #2C5282;
  --warm: #DD6B20;
  --line: #e2e8f0;
  --paper: #f7fafc;

  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--ink);
  background-color: var(--paper);
  padding: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  border: 1px solid var(--line);
}

.chapter-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 1rem;
}

.chapter-title {
  font-size: 2rem;
  color: var(--accent);
  margin: 0 0 0.5rem 0;
}

.chapter-intro {
  color: var(--muted);
  font-size: 1rem;
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.section-heading {
  font-size: 1.25rem;
  color: var(--accent);
  margin-bottom: 1rem;
  border-left: 4px solid var(--accent);
  padding-left: 0.5rem;
}

.text-block {
  margin-bottom: 1rem;
  font-size: 0.95rem;
}

.highlight-warning {
  color: var(--warm);
  font-weight: bold;
  background: rgba(221, 107, 32, 0.1);
  padding: 0 0.25rem;
}

.source-box {
  margin-top: 1.5rem;
  padding: 1rem;
  background: #edf2f7;
  border-radius: 4px;
}

.source-label {
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
}

.source-btn {
  background: white;
  border: 1px solid var(--line);
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  cursor: pointer;
  margin-right: 0.5rem;
  color: var(--ink);
}

.source-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
}

.control-group {
  margin-bottom: 1.5rem;
}

.control-label {
  display: block;
  font-size: 0.9rem;
  margin-bottom: 0.5rem;
  color: var(--ink);
}

.task-select {
  width: 100%;
  padding: 0.5rem;
  font-size: 1rem;
  border: 1px solid var(--line);
  background: white;
  color: var(--ink);
}

.chart-container {
  background: white;
  border: 1px solid var(--line);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  min-height: 250px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.chart-bars {
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  height: 200px;
  gap: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid var(--line);
}

.chart-bar {
  width: 40px;
  background: var(--accent);
  transition: height 0.3s ease;
  position: relative;
  min-height: 2px;
}

.chart-bar.warning {
  background: var(--warm);
}

.chart-bar-label {
  position: absolute;
  bottom: -25px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.75rem;
  white-space: nowrap;
  color: var(--muted);
}

.chart-bar-value {
  position: absolute;
  top: -20px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 0.75rem;
  font-weight: bold;
  color: var(--ink);
}

.chart-legend {
  margin-top: 1rem;
  font-size: 0.85rem;
  color: var(--muted);
}

.chart-note {
  font-size: 0.85rem;
  color: var(--muted);
  font-style: italic;
}

.cost-analysis-section {
  border-top: 2px solid var(--line);
  padding-top: 2rem;
}

.cost-chart .chart-bar {
  background: #48bb78;
}

.cost-ratio-display {
  background: #edf2f7;
  padding: 1rem;
  margin-bottom: 1rem;
  font-size: 0.9rem;
}

.ratio-value {
  font-weight: bold;
  color: var(--accent);
}

.reset-btn {
  background: var(--ink);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  cursor: pointer;
}

.reset-btn:hover {
  opacity: 0.9;
}

@media (prefers-reduced-motion: reduce) {
  .chart-bar {
    transition: none;
  }
}
.content-grid{grid-template-columns:minmax(0,1fr)}.chart-bars{height:auto;display:block;padding:0;border:0}.bleu-comparison-row{display:grid;grid-template-columns:160px minmax(0,1fr) 46px;gap:12px;align-items:center;margin:15px 0;font-size:13px}.bleu-track{height:18px;background:#edf0ed}.bleu-bar{height:18px;background:#265976}.bleu-comparison-row output{font-variant-numeric:tabular-nums;text-align:right}.chart-container{min-height:0;padding:22px 0;border:0;background:transparent}.chart-note{font-size:13px}#cost-chart{overflow-x:auto}#cost-chart table{min-width:540px}.section-heading{border-left:0;padding-left:0}@media(max-width:480px){.bleu-comparison-row{grid-template-columns:110px minmax(0,1fr) 40px;gap:8px}.bleu-model-name{font-size:12px;overflow-wrap:anywhere}}

section[id]{--ink:#233342;--muted:#596877;--accent:#265976;--warm:#ad472d;--line:#d6dcd9;--paper:#fcfbf8;background:transparent;border:0;border-radius:0;padding:0;max-width:100%;color:var(--ink)}
section[id] h2{color:#233342;font-family:Georgia,"Noto Serif SC",SimSun,serif;font-weight:500;font-size:29px;line-height:1.5}
section[id]>header{border-bottom:1px solid #d6dcd9}section[id] p{line-height:1.9}
section[id] [class*="formula"]{max-width:100%;overflow-x:auto}
section[id] [class*="panel"],section[id] [class*="workbench"]{box-shadow:none}
@media(max-width:600px){section[id] div{min-width:0;max-width:100%}section[id] h2{font-size:25px}section[id] [class*="grid"]{grid-template-columns:minmax(0,1fr)}section[id] .pm-matrix-grid{grid-template-columns:repeat(3,minmax(0,1fr))}section[id] .pm-input-row input{min-width:0;flex:1;width:0}section[id] .pm-control-group{flex-wrap:wrap}section[id] .pm-control-group label{min-width:0;flex-basis:100%}section[id] .pm-section-header{flex-wrap:wrap}section[id] .pm-lab-panel,section[id] .interaction-panel{padding:14px}section[id] .pm-head-visual{display:block}section[id] .pm-control-group span{min-width:0}}

javascript:
(function() {
  'use strict';

  // 数据解析辅助函数
  function parseScientific(str) {
    if (str === null || str === undefined || str === '') return null;
    const num = Number(str);
    return isNaN(num) ? null : num;
  }

  // 获取表格数据
  function getTableData() {
    if (!window.paperMindData || !window.paperMindData.tables) {
      console.warn('paperMindData not available');
      return null;
    }
    const table = window.paperMindData.tables.find(t => t.id === 'p8-Table_2');
    return table || null;
  }

  // 渲染 BLEU 图表
  function renderBleuChart(task) {
    const table = getTableData();
    if (!table) return;

    const container = document.querySelector('#result-chart .chart-bars');
    const legend = document.querySelector('#result-chart .chart-legend');
    if (!container) return;

    container.innerHTML = '';
    legend.innerHTML = '';

    const colKey = task === 'ende' ? 'BLEU EN-DE' : 'BLEU EN-FR';
    const models = table.rows.map(row=>({id:row.id,label:row.label,warning:row.label.includes('Transformer')&&task==='enfr'}));
    let maxVal = 0;
    const dataPoints = [];

    models.forEach(m => {
      const row = table.rows.find(r => r.id === m.id);
      if (row && row.values && row.values[colKey] !== null) {
        const val = parseScientific(row.values[colKey]);
        if (val !== null) {
          dataPoints.push({ label: m.label, value: val, warning: m.warning });
          if (val > maxVal) maxVal = val;
        }
      }
    });

    dataPoints.forEach(dp=>{
      const row=document.createElement('div');row.className='bleu-comparison-row';
      const name=document.createElement('span');name.textContent=dp.label;name.className='bleu-model-name';
      const track=document.createElement('div');track.className='bleu-track';
      const bar=document.createElement('div');bar.className='bleu-bar';bar.dataset.bleu=dp.value;bar.dataset.model=dp.label;bar.style.width=(dp.value/maxVal*100)+'%';if(dp.label.includes('Transformer'))bar.style.background='#ad472d';track.append(bar);
      const value=document.createElement('output');value.textContent=dp.value;row.append(name,track,value);container.append(row);
    });
    legend.textContent = task==='enfr'?'同一测试集 newstest2014 · 柱长从0开始。此图按原表41.8绘制；正文另写41.0，原文未解释差异，不推测原因。':'WMT 2014 · newstest2014 · BLEU越高越好。未报告的语言任务不补零；柱长从0开始。';
  }

  // 渲染成本图表
  function renderCostChart(){
    const table=getTableData(),container=document.querySelector('#cost-chart .chart-bars'),ratio=document.getElementById('cost-ratio-output');if(!table||!container)return;
    container.replaceChildren();
    const t=document.createElement('table');t.innerHTML='<thead><tr><th>模型</th><th>EN-DE成本</th><th>EN-FR成本</th><th>原表合并列</th></tr></thead>';const b=document.createElement('tbody');
    for(const row of table.rows){if(!['row_5','row_7','row_10'].includes(row.id))continue;const tr=document.createElement('tr');for(const value of [row.label,row.values['Cost EN-DE FLOPs'],row.values['Cost EN-FR FLOPs'],row.values['Merged cost FLOPs']]){const td=document.createElement('td');td.textContent=value||'未分别列出';tr.append(td);}b.append(tr);}t.append(b);container.append(t);
    if(ratio)ratio.textContent='单位为原文估计训练 FLOPs。Transformer 的成本在原表跨语言合并单元格中列出；本页保留该口径，不据此推算精确的同语种降幅。原文“低于四分之一”的说法可回查正文。';
  }
  // 初始化
  function init() {
    const taskSelect = document.getElementById('result-task');
    const resetBtn = document.getElementById('reset-charts');

    if (taskSelect) {
      taskSelect.addEventListener('change', function(e) {
        renderBleuChart(e.target.value);
      });
      // 初始渲染
      renderBleuChart(taskSelect.value);
    }

    renderCostChart();

    if (resetBtn) {
      resetBtn.addEventListener('click', function() {
        if (taskSelect) taskSelect.value = 'ende';
        renderBleuChart('ende');
        renderCostChart();
      });
    }

    // 来源按钮事件代理
    document.addEventListener('click', function(e) {
      if (e.target.matches('.source-btn')) {
        const sourceId = e.target.getAttribute('data-source');
        // 宿主内核处理桥接，此处仅做视觉反馈或预留接口
        // 实际环境中会触发来源高亮
        e.target.blur();
      }
    });
  }

  // 等待 DOM 就绪
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
